diff --git a/src/lib/OpenEXR/ImfIDManifest.cpp b/src/lib/OpenEXR/ImfIDManifest.cpp
index 4a41f27c..67350107 100644
--- a/src/lib/OpenEXR/ImfIDManifest.cpp
+++ b/src/lib/OpenEXR/ImfIDManifest.cpp
@@ -351,7 +351,7 @@ IDManifest::init (const char* data, const char* endOfData)

     unsigned int version;
     Xdr::read<CharPtrIO> (data, version);
-    if (version != 0)
+    if (version > 1)
     {
         throw IEX_NAMESPACE::InputExc ("Unrecognized IDmanifest version");
     }

diff --git a/src/lib/OpenEXR/ImfIDManifest.cpp b/src/lib/OpenEXR/ImfIDManifest.cpp
index e9b5bd75..6f1f4cfa 100644
--- a/src/lib/OpenEXR/ImfIDManifest.cpp
+++ b/src/lib/OpenEXR/ImfIDManifest.cpp
@@ -362,6 +362,21 @@ IDManifest::init (const char* data, const char* endOfData)
         throw IEX_NAMESPACE::InputExc ("Unrecognized IDmanifest version");
     }

+    //
+    // version 1 manifests carry an additional flags word immediately
+    // after the version field; only manifests with no flags set are
+    // currently supported
+    //
+    if (version == 1)
+    {
+        unsigned int flags;
+        Xdr::read<CharPtrIO> (data, flags);
+        if (flags != 0)
+        {
+            throw IEX_NAMESPACE::InputExc ("Unsupported IDmanifest flags");
+        }
+    }
+
